package com.autoops.audit.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="audit_events")public class AuditEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id")private Long userId;@Column(nullable=false)private String action;@Column(name="entity_type",nullable=false)private String entityType;@Column(name="entity_id")private Long entityId;@Column(columnDefinition="jsonb")private String metadata;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();}
